814	    store.imports.push({
815	      uid: im.uid,
816	      bookingId: im.bookingId,
817	      start: im.start,
818	      end: im.end,
819	      resourceIds: [...rseen].sort(),
820	    });
821	  });
822	
823	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
824	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
825	  store.series.sort((a, b) => a.id.localeCompare(b.id));
