852	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
853	async function saveStore(file: string, store: Store): Promise<void> {
854	  let json: string;
855	  try {
856	    json = JSON.stringify(store, null, 2) + '\n';
857	  } catch (err) {
858	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
859	  }
860	  const tmp = `${file}.${process.pid}.tmp`;
861	  try {
