883	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
884	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
885	  const problems: string[] = [];
886	  const seen = new Set<string>();
887	  const dupes: string[] = [];
888	  for (const id of rawIds) {
889	    if (seen.has(id)) {
890	      if (!dupes.includes(id)) dupes.push(id);
891	    }
892	    seen.add(id);
893	  }
894	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
895	
896	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
897	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
898	
899	  if (problems.length > 0) throw new BizError(problems.join('\n'));
900	  return [...seen].sort();
901	}
