903	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
904	  return mergeIntervals(
905	    r.open.map(
906	      ([s, e]) =>
907	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
908	    ),
909	  );
910	}
