912	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
913	function subtractSegments(
914	  segments: Array<[number, number]>,
915	  cuts: Array<[number, number]>,
916	): Array<[number, number]> {
917	  let result = segments;
918	  for (const [cs, ce] of mergeIntervals(cuts)) {
919	    const next: Array<[number, number]> = [];
920	    for (const [s, e] of result) {
921	      if (ce <= s || e <= cs) {
922	        next.push([s, e]);
923	        continue;
924	      }
925	      if (s < cs) next.push([s, cs]);
926	      if (ce < e) next.push([ce, e]);
927	    }
928	    result = next;
929	  }
930	  return result;
931	}
