933	// 某资源的有效停用记录（按开始时间、标识排序）
934	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
935	  return store.closures
936	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
937	    .sort(
938	      (a, b) =>
939	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
940	        a.id.localeCompare(b.id),
941	    );
942	}
