959	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
960	function findCoverageGaps(
961	  store: Store,
962	  ids: string[],
963	  startMin: number,
964	  endMin: number,
965	): CoverageGap[] {
966	  const gaps: CoverageGap[] = [];
967	  for (const id of ids) {
968	    const r = store.resources.find((x) => x.id === id)!;
969	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
970	    const closures = activeClosuresOf(store, id).filter((c) => {
971	      const cs = parseDateTime(c.start, '停用开始时间');
972	      const ce = parseDateTime(c.end, '停用结束时间');
973	      return cs < endMin && startMin < ce;
974	    });
975	    gaps.push({id, r, closures});
976	  }
977	  return gaps;
978	}
