980	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
981	function gapLines(gaps: CoverageGap[], indent: string): string[] {
982	  const lines: string[] = [];
983	  for (const g of gaps) {
984	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
985	    for (const c of g.closures) {
986	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
987	    }
988	  }
989	  return lines;
990	}
