992	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
993	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
994	  const failing = findCoverageGaps(store, ids, startMin, endMin);
995	  if (failing.length > 0) {
996	    throw new BizError(
997	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
998	        gapLines(failing, '').join('\n'),
999	    );
1000	  }
1001	}
