1008	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1009	function findConflicts(
1010	  store: Store,
1011	  ids: string[],
1012	  startMin: number,
1013	  endMin: number,
1014	  excludeBookingId?: string,
1015	): Conflict[] {
1016	  const wanted = new Set(ids);
1017	  const conflicts: Conflict[] = [];
1018	  for (const b of store.bookings) {
1019	    if (b.status !== 'active') continue;
1020	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1021	    const bStart = parseDateTime(b.start, '预约开始时间');
1022	    const bEnd = parseDateTime(b.end, '预约结束时间');
1023	    const overlap = bStart < endMin && startMin < bEnd;
1024	    if (!overlap) continue;
1025	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1026	    if (shared.length > 0) conflicts.push({booking: b, shared});
1027	  }
1028	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1029	  return conflicts;
1030	}
1031	
1032	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1033	  if (conflicts.length === 0) return;
1034	  const lines = conflicts.map(
1035	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1036	  );
1037	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1038	}
