1050	function splitGlobalArgs(argv: string[]): GlobalArgs {
1051	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1052	  for (let i = 0; i < argv.length; i++) {
1053	    const a = argv[i];
1054	    if (a === '-h' || a === '--help') {
1055	      result.help = true;
1056	    } else if (a === '--data') {
1057	      const v = argv[++i];
1058	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1059	      result.dataFile = v;
1060	    } else if (a.startsWith('--data=')) {
1061	      result.dataFile = a.slice('--data='.length);
1062	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1063	    } else {
1064	      result.rest.push(a);
1065	    }
1066	  }
1067	  return result;
