1070	interface ParsedFlags {
1071	  values: Map<string, string[]>;
1072	  positionals: string[];
1073	}
1074	
1075	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1076	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1077	  const allowedSet = new Set(allowed);
1078	  const multiSet = new Set(multi);
1079	  const values = new Map<string, string[]>();
1080	  const positionals: string[] = [];
1081	
1082	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1083	    if (inline !== undefined) return [inline, index];
1084	    const v = args[index + 1];
1085	    if (v === undefined || v.startsWith('-')) {
1086	      throw new UsageError(`选项 --${key} 缺少值`);
1087	    }
1088	    return [v, index + 1];
1089	  };
1090	
1091	  for (let i = 0; i < args.length; i++) {
1092	    const a = args[i];
1093	    if (a.startsWith('--')) {
1094	      let key: string;
1095	      let inline: string | undefined;
1096	      const eq = a.indexOf('=');
1097	      if (eq >= 0) {
1098	        key = a.slice(2, eq);
1099	        inline = a.slice(eq + 1);
1100	      } else {
1101	        key = a.slice(2);
1102	      }
1103	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1104	      let v: string;
1105	      [v, i] = takeValue(key, inline, i);
1106	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1107	      if (!multiSet.has(key) && values.has(key)) {
1108	        throw new UsageError(`选项 --${key} 只能指定一次`);
1109	      }
1110	      const list = values.get(key) ?? [];
1111	      list.push(v);
1112	      values.set(key, list);
1113	    } else if (a.startsWith('-') && a !== '-') {
1114	      throw new UsageError(`未知参数: ${a}`);
1115	    } else {
1116	      positionals.push(a);
1117	    }
1118	  }
1119	  return {values, positionals};
1120	}
1121	
1122	function requireFlag(values: Map<string, string[]>, key: string): string {
1123	  const v = values.get(key)?.[0];
1124	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1125	  return v;
1126	}
