1227	  if (booking.status === 'cancelled') {
1228	    throw new BizError(`预约 ${id} 已取消，不能改期`);
1229	  }
1230	
1231	  const hasTime = values.has('start') || values.has('end');
1232	  const hasResource = values.has('resource');
1233	  if (!hasTime && !hasResource) {
1234	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
1235	  }
