1243	  }
1244	
1245	  let ids: string[] = booking.resourceIds;
1246	  if (hasResource) {
1247	    const resourceArgs = values.get('resource')!;
1248	    ids = resolveResourceIds(store, resourceArgs);
1249	  }
1250	
1251	  assertOpenCoverage(store, ids, startMin, endMin);
1252	  // 改期检查排除自身
1253	  assertNoConflicts(findConflicts(store, ids, startMin, endMin, id), store);
1254	
1255	  // 全部可用后整体替换旧安排并落盘；失败则本进程内存与磁盘上的原安排都不变。
