1259	  booking.resourceIds = ids;
1260	  await saveStore(file, store);
1261	  console.log(`已改期预约 ${id}（标识保持不变）`);
1262	  if (booking.seriesId) console.log(`  所属系列: ${booking.seriesId}（改期后仍属该系列）`);
