1303	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1304	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1305	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1306	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1307	  }
1308	  const o = raw as Record<string, unknown>;
1309	  for (const k of Object.keys(o)) {
1310	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1311	  }
1312	  if (!Array.isArray(o.items)) {
1313	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1314	  }
1315	  const items = o.items as unknown[];
1316	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1317	
1318	  const problems: string[] = [];
1319	  const records: Array<Record<string, unknown> | null> = [];
1320	  items.forEach((it, idx) => {
1321	    const at = `第 ${idx + 1} 项`;
1322	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1323	      problems.push(`${at} 必须是对象`);
1324	      records.push(null);
1325	      return;
1326	    }
1327	    const rec = it as Record<string, unknown>;
1328	    for (const k of Object.keys(rec)) {
1329	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1330	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1331	      }
1332	    }
1333	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1334	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1335	    }
1336	    if (typeof rec.start !== 'string' || rec.start === '') {
1337	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1338	    }
1339	    if (typeof rec.end !== 'string' || rec.end === '') {
1340	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1341	    }
1342	    if (!Array.isArray(rec.resourceIds)) {
1343	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1344	    } else {
1345	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1346	      rec.resourceIds.forEach((rid, j) => {
1347	        if (typeof rid !== 'string' || rid === '') {
1348	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1349	        }
1350	      });
1351	    }
1352	    records.push(rec);
1353	  });
1354	  if (problems.length > 0) {
1355	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1356	  }
1357	  return records as Array<Record<string, unknown>>;
1358	}
