1897	async function cmdCreateSeries(args: string[]): Promise<void> {
1898	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end', 'count'], ['resource']);
1899	  if (positionals.length > 0) throw new UsageError(`create-series 不接受位置参数: ${positionals.join(' ')}`);
1900	
1901	  const resourceArgs = values.get('resource');
1902	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
1903	  const startRaw = requireFlag(values, 'start');
1904	  const endRaw = requireFlag(values, 'end');
1905	  const count = parseOccurrences(requireFlag(values, 'count'));
1906	
1907	  const file = activeDataFile;
1908	  const store = await loadStore(file);
1909	
1910	  const ids = resolveResourceIds(store, resourceArgs);
1911	  const startMin = parseDateTime(startRaw, '首项开始时间');
1912	  const endMin = parseDateTime(endRaw, '首项结束时间');
1913	  if (endMin <= startMin) {
1914	    throw new BizError(`首项结束时间必须晚于开始时间（开始: ${startRaw}，结束: ${endRaw}），允许跨日`);
1915	  }
1916	
1917	  // 先展开全部成员时间（含跨月、闰日、跨年、年份范围校验）
1918	  const members = planWeeklyMembers(startMin, endMin, count);
1919	
1920	  // 逐项校验：开放覆盖、与既有有效预约冲突、与系列内其他成员冲突
1921	  const failures: MemberFailure[] = [];
1922	  for (let i = 0; i < members.length; i++) {
1923	    const m = members[i];
1924	    const gaps = findCoverageGaps(store, ids, m.startMin, m.endMin);
1925	    const conflicts = findConflicts(store, ids, m.startMin, m.endMin);
1926	    const internal: Array<{other: PlannedMember; otherIndex: number}> = [];
1927	    for (let j = 0; j < members.length; j++) {
1928	      if (j === i) continue;
1929	      const o = members[j];
1930	      if (o.startMin < m.endMin && m.startMin < o.endMin) {
1931	        internal.push({other: o, otherIndex: j});
1932	      }
1933	    }
1934	    if (gaps.length > 0 || conflicts.length > 0 || internal.length > 0) {
1935	      failures.push({index: i, startRaw: m.startRaw, endRaw: m.endRaw, gaps, conflicts, internal});
1936	    }
1937	  }
1938	
1939	  if (failures.length > 0) {
1940	    // 按发生顺序报告所有失败项；任一项不满足则整批失败，不分配任何标识、不写文件
1941	    const blocks = failures.map((f) => {
1942	      const lines = [`第 ${f.index + 1} 项 ${f.startRaw} → ${f.endRaw}：`];
1943	      if (f.gaps.length > 0) {
1944	        lines.push('  开放不足资源:');
1945	        lines.push(...gapLines(f.gaps, '    '));
1946	      }
1947	      if (f.conflicts.length > 0) {
1948	        lines.push('  与以下既有预约冲突:');
1949	        for (const c of f.conflicts) {
1950	          lines.push(
1951	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1952	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1953	          );
1954	        }
1955	      }
1956	      if (f.internal.length > 0) {
1957	        lines.push('  与系列内其他成员冲突:');
1958	        for (const x of f.internal) {
1959	          lines.push(
1960	            `    - 第 ${x.otherIndex + 1} 项（${x.other.startRaw} → ${x.other.endRaw}）：双方时间重叠`,
1961	          );
1962	        }
1963	      }
1964	      return lines.join('\n');
1965	    });
1966	    throw new BizError(
1967	      `系列创建失败：共 ${failures.length} 项不满足条件（按发生顺序），整批未创建：\n${blocks.join('\n')}`,
1968	    );
1969	  }
1970	
1971	  // 全部验证通过：分配一个系列标识与每项预约标识，一次性落盘。
1972	  // 标识在此刻才生成，任何失败都不会推进计数。
1973	  store.seriesSeq += 1;
1974	  const seriesId = `S${String(store.seriesSeq).padStart(4, '0')}`;
1975	  const assigned: Array<{id: string; m: PlannedMember}> = [];
1976	  for (const m of members) {
1977	    store.bookingSeq += 1;
1978	    const id = `B${String(store.bookingSeq).padStart(4, '0')}`;
1979	    store.bookings.push({
1980	      id,
1981	      resourceIds: ids,
1982	      start: m.startRaw,
1983	      end: m.endRaw,
1984	      status: 'active',
1985	      seriesId,
1986	    });
1987	    assigned.push({id, m});
1988	  }
1989	  store.series.push({id: seriesId});
1990	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1991	  store.series.sort((a, b) => a.id.localeCompare(b.id));
1992	  await saveStore(file, store);
1993	
1994	  console.log(`已创建按周重复系列 ${seriesId}（共 ${count} 项，每周一次，全部成员使用相同资源）`);
1995	  console.log(`  资源: ${formatResourceIds(store, ids)}`);
1996	  assigned.forEach(({id, m}, i) => {
1997	    console.log(`  第 ${i + 1} 项 ${id}: ${m.startRaw} → ${m.endRaw}`);
1998	  });
1999	}
