2290	function flexBusySegments(
2291	  store: Store,
2292	  ids: string[],
2293	  wStart: number,
2294	  wEnd: number,
2295	): Array<[number, number]> {
2296	  const wanted = new Set(ids);
2297	  const cuts: Array<[number, number]> = [];
2298	  for (const b of store.bookings) {
2299	    if (b.status !== 'active') continue;
2300	    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
2301	    const bStart = parseDateTime(b.start, '预约开始时间');
2302	    const bEnd = parseDateTime(b.end, '预约结束时间');
2303	    const a = Math.max(bStart, wStart);
2304	    const c = Math.min(bEnd, wEnd);
2305	    if (a < c) cuts.push([a, c]);
2306	  }
2307	  return mergeIntervals(cuts);
2308	}
