2598	// iCalendar 导入（import-ical）
2599	// 读取 UTF-8 的 VCALENDAR（VERSION:2.0，至少一个独立 VEVENT），为新事件各创建
2600	// 一项普通预约（不加入系列、不自动处理候补），全部使用命令行给定的同一资源集合。
2601	// UID 在同一数据文件中永久关联首次生成的预约；相同 UID 且时间、资源集合与首次
2602	// 导入一致为重放（返回原预约当前安排与状态，不做任何改动），不一致则整批拒绝。
2603	// ---------------------------------------------------------------------------
2604	
2605	// 一个解析完成的 VEVENT（时间已换算为营业地分钟数与 YYYY-MM-DDTHH:mm 文本）
2606	interface IcalEvent {
2607	  uid: string; // 解码后的 UID（区分大小写）
2608	  startRaw: string;
2609	  endRaw: string;
2610	  startMin: number;
2611	  endMin: number;
2612	}
2613	
2614	// 标准折行展开：以空格或制表符开头的行是上一行的延续（去掉首个空白字符拼接）。
2615	// 同时支持 CRLF 与 LF 行尾；空行忽略（文件末尾换行自然被吞掉）。
2616	function unfoldIcalLines(text: string, bad: (reason: string) => never): string[] {
2617	  const lines: string[] = [];
2618	  for (const raw of text.split(/\r\n|\n/)) {
2619	    if (raw === '') continue;
2620	    if (raw.startsWith(' ') || raw.startsWith('\t')) {
2621	      if (lines.length === 0) bad('文件以折行续行开头，缺少被延续的内容行');
2622	      lines[lines.length - 1] += raw.slice(1);
2623	    } else {
2624	      lines.push(raw);
2625	    }
2626	  }
2627	  return lines;
2628	}
2629	
2630	// 拆分内容行为 属性名;参数:值；属性名忽略大小写（统一转大写返回）
2631	function parseContentLine(
2632	  line: string,
2633	  bad: (reason: string) => never,
2634	): {name: string; params: string[]; value: string} {
2635	  const colon = line.indexOf(':');
2636	  if (colon < 0) bad(`内容行缺少 “:”: “${line}”`);
2637	  const head = line.slice(0, colon);
2638	  const value = line.slice(colon + 1);
2639	  const segs = head.split(';');
2640	  if (!/^[A-Za-z0-9-]+$/.test(segs[0])) bad(`属性名非法: “${segs[0]}”`);
2641	  return {name: segs[0].toUpperCase(), params: segs.slice(1), value};
2642	}
2643	
2644	// UID 文本转义解码：\\ → \，\n/\N → 换行，\, → ,，\; → ;；其余反斜杠序列原样保留。
2645	// 解码后再比较，因此同一 UID 的不同转义写法视为相同。
2646	function unescapeIcalText(value: string): string {
2647	  return value.replace(/\\(\\|[nN]|,|;)/g, (_all, ch: string) =>
2648	    ch === 'n' || ch === 'N' ? '\n' : ch,
2649	  );
2650	}
