2678	// DTSTART/DTEND 的参数：仅允许显式的 VALUE=DATE-TIME（即默认浮动时间）；
2679	// 全天（VALUE=DATE）、时区（TZID）及其他参数一律拒绝
2680	function assertFloatingDateTimeParams(
2681	  params: string[],
2682	  label: string,
2683	  bad: (reason: string) => never,
2684	): void {
2685	  for (const p of params) {
2686	    const upper = p.toUpperCase();
2687	    if (upper === 'VALUE=DATE-TIME') continue;
2688	    if (upper === 'VALUE=DATE') bad(`${label}不支持全天事件（VALUE=DATE）`);
2689	    if (upper.startsWith('TZID=')) bad(`${label}不支持时区时间（TZID），仅接受浮动时间`);
2690	    bad(`${label}携带不支持的参数 “${p}”，仅接受浮动时间 YYYYMMDDTHHmmss`);
2691	  }
2692	}
