2831	async function cmdImportIcal(args: string[]): Promise<void> {
2832	  const {values, positionals} = parseFlags(args, ['resource'], ['resource']);
2833	  if (positionals.length !== 1) {
2834	    throw new UsageError('用法: import-ical <iCalendar 文件> --resource <标识> [--resource <标识> ...]');
2835	  }
2836	  const resourceArgs = values.get('resource');
2837	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
2838	  const icalFile = positionals[0];
2839	
2840	  const file = activeDataFile;
2841	  const store = await loadStore(file);
2842	  // 新事件统一使用该资源集合（至少一个不同的已登记资源，按标识排序）
2843	  const ids = resolveResourceIds(store, resourceArgs);
2844	
2845	  // 输入文件不可读、结构非法均整批失败，不触碰数据文件
2846	  let text: string;
2847	  try {
2848	    text = await readFile(icalFile, 'utf8');
2849	  } catch (err) {
2850	    throw new BizError(`无法读取 iCalendar 文件 ${icalFile}: ${(err as Error).message}`);
2851	  }
2852	  const events = parseIcalFile(text, icalFile);
2853	
2854	  // 区分重放与新增：UID 命中既有导入身份即重放候选；
2855	  // 时间与资源集合（顺序无关）须与首次导入快照一致，否则整批拒绝
2856	  const importByUid = new Map(store.imports.map((r) => [r.uid, r]));
2857	  interface ImportItem {
2858	    ev: IcalEvent;
2859	    index: number; // 0 基，按文件顺序
2860	    replay?: ImportRec;
2861	  }
2862	  const mismatches: string[] = [];
2863	  const items: ImportItem[] = events.map((ev, index) => {
2864	    const rec = importByUid.get(ev.uid);
2865	    if (rec === undefined) return {ev, index};
2866	    const sameTime = rec.start === ev.startRaw && rec.end === ev.endRaw;
2867	    const sameResources =
2868	      rec.resourceIds.length === ids.length && rec.resourceIds.every((x, j) => x === ids[j]);
2869	    if (!sameTime || !sameResources) {
2870	      mismatches.push(
2871	        `第 ${index + 1} 项 UID “${ev.uid}”：首次导入为 ${rec.start} → ${rec.end}` +
2872	          `（资源 ${rec.resourceIds.join('、')}），本次为 ${ev.startRaw} → ${ev.endRaw}` +
2873	          `（资源 ${ids.join('、')}）`,
2874	      );
2875	    }
2876	    return {ev, index, replay: rec};
2877	  });
2878	  if (mismatches.length > 0) {
2879	    throw new BizError(
2880	      `iCalendar 导入被拒绝：${mismatches.length} 个 UID 的时间或资源集合与首次导入不一致` +
2881	        '（相同 UID 不会覆盖本地安排，整批未导入）：\n' +
2882	        mismatches.map((m) => `- ${m}`).join('\n'),
2883	    );
2884	  }
