2888	  const newItems = items.filter((it) => it.replay === undefined);
2889	  interface ImportFailure {
2890	    item: ImportItem;
2891	    gaps: CoverageGap[];
2892	    external: Conflict[]; // 与全部既有有效预约（含重放项关联预约）的冲突
2893	    internal: Array<{other: ImportItem; shared: string[]}>; // 批内新项之间的冲突
2894	  }
2895	  const failures: ImportFailure[] = [];
2896	  for (const it of newItems) {
2897	    const gaps = findCoverageGaps(store, ids, it.ev.startMin, it.ev.endMin);
2898	    const external = findConflicts(store, ids, it.ev.startMin, it.ev.endMin);
2899	    const internal: ImportFailure['internal'] = [];
2900	    for (const o of newItems) {
2901	      if (o === it) continue;
2902	      const overlap = o.ev.startMin < it.ev.endMin && it.ev.startMin < o.ev.endMin;
2903	      // 新项统一使用同一资源集合，时间重叠即共同资源冲突
2904	      if (overlap) internal.push({other: o, shared: ids});
