2906	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
2907	      failures.push({item: it, gaps, external, internal});
2908	    }
2909	  }
2910	
2911	  if (failures.length > 0) {
2912	    // 按文件顺序报告全部失败 UID、时间、不足资源（含相关停用）与全部冲突；批内冲突双方互列
2913	    const blocks = failures.map(({item, gaps, external, internal}) => {
2914	      const lines = [
2915	        `第 ${item.index + 1} 项 UID “${item.ev.uid}”（${item.ev.startRaw} → ${item.ev.endRaw}）：`,
2916	      ];
2917	      if (gaps.length > 0) {
2918	        lines.push('  开放不足资源:');
2919	        lines.push(...gapLines(gaps, '    '));
2920	      }
2921	      if (external.length > 0) {
2922	        lines.push('  冲突预约:');
2923	        for (const c of external) {
2924	          lines.push(
2925	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
2926	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
2927	          );
2928	        }
2929	      }
2930	      if (internal.length > 0) {
2931	        lines.push('  批内冲突:');
2932	        for (const x of internal) {
2933	          lines.push(
2934	            `    - 第 ${x.other.index + 1} 项 UID “${x.other.ev.uid}”` +
2935	              `（${x.other.ev.startRaw} → ${x.other.ev.endRaw}）` +
2936	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
2937	          );
2938	        }
2939	      }
2940	      return lines.join('\n');
2941	    });
2942	    throw new BizError(
2943	      `iCalendar 导入失败：共 ${failures.length} 项新事件不满足条件（按文件顺序），整批未导入：\n${blocks.join('\n')}`,
2944	    );
2945	  }
