2947	  const replayCount = items.length - newItems.length;
2948	  const renderItem = (it: ImportItem, bookingId: string, isNew: boolean): string[] => {
2949	    if (isNew) {
2950	      return [
2951	        `- 第 ${it.index + 1} 项 UID “${it.ev.uid}” → 新预约 ${bookingId}（新增，普通预约，不属于任何系列）`,
2952	        `    时间: ${it.ev.startRaw} → ${it.ev.endRaw}`,
2953	        `    资源: ${formatResourceIds(store, ids)}`,
2954	      ];
2955	    }
2956	    // 重放：返回原预约的当前安排与状态，不做任何改动（已取消/被撤销也不复活）
2957	    const b = store.bookings.find((x) => x.id === bookingId)!;
2958	    const statusLabel = b.status === 'active' ? '已预约' : '已取消';
2959	    return [
2960	      `- 第 ${it.index + 1} 项 UID “${it.ev.uid}” → 预约 ${bookingId}（重放，未做改动）`,
