2962	      `    当前安排: ${b.start} → ${b.end}`,
2963	      `    当前资源: ${formatResourceIds(store, b.resourceIds)}`,
2964	    ];
2965	  };
2966	
2967	  if (newItems.length === 0) {
2968	    // 全为重放：不写文件、不推进任何计数
2969	    console.log(
2970	      `iCalendar 导入完成：共 ${items.length} 项，全部为重放（未写入数据文件，标识计数不变）`,
