60	function tempDir(t: {after: (fn: () => void) => void}): string {
61	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-batch-test-'));
62	  t.after(() => rmSync(dir, {recursive: true, force: true}));
63	  return dir;
64	}
65	
66	function addResource(df: string, name: string, open: Array<[string, string]> = OPEN_ALL): void {
67	  const args = ['add-resource', '--type', 'venue', '--name', name];
68	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
69	  ok(df, args, `登记资源 ${name}`);
70	}
71	
72	function createBooking(df: string, resources: string[], start: string, end: string, ctx: string): void {
73	  const args = ['create-booking'];
74	  for (const r of resources) args.push('--resource', r);
75	  args.push('--start', start, '--end', end);
76	  ok(df, args, ctx);
77	}
78	
79	function writeManifest(dir: string, name: string, items: unknown[]): string {
80	  const p = join(dir, name);
81	  writeFileSync(p, JSON.stringify({items}, null, 2) + '\n');
82	  return p;
83	}
84	
85	// 由新进程之外直接读取保存结果（JSON 数据文件本身即持久化结果）
86	function readStore(df: string): any {
87	  return JSON.parse(readFileSync(df, 'utf8'));
88	}
89	
90	function bookingOf(store: any, id: string): any {
91	  const b = store.bookings.find((x: any) => x.id === id);
92	  assert.ok(b, `预约 ${id} 应存在`);
93	  return b;
94	}
95	
96	function assertArrangement(
97	  store: any,
98	  id: string,
99	  start: string,
100	  end: string,
101	  resources: string[],
102	  ctx: string,
103	): void {
104	  const b = bookingOf(store, id);
105	  assert.equal(b.start, start, `[${ctx}] ${id} 开始时间`);
106	  assert.equal(b.end, end, `[${ctx}] ${id} 结束时间`);
107	  assert.deepEqual(b.resourceIds, [...resources].sort(), `[${ctx}] ${id} 资源集合`);
108	}
109	
110	function assertFileBytes(df: string, expected: Buffer, ctx: string): void {
111	  assert.ok(expected.equals(readFileSync(df)), `[${ctx}] 数据文件应逐字节保留`);
112	}
