356	  assertArrangement(store, 'B0002', '2026-10-12T13:00', '2026-10-12T14:00', ['R0001'], '整笔不变');
357	  assertArrangement(store, 'B0003', '2026-10-12T16:00', '2026-10-12T17:00', ['R0001'], '整笔不变');
358	  assert.equal(store.batchOps[0].status, 'active', '记录状态不变');
359	  assert.equal(store.batchSeq, 1, '操作计数不变');
360	});
361	
362	// ---------------------------------------------------------------------------
363	// 5a. 恢复受阻：有效停用 + 批外预约同时阻挡，解除后恢复成功
364	// ---------------------------------------------------------------------------
365	
366	test('撤销恢复受阻：有效停用与批外预约阻挡全部列出，解除阻挡后恢复成功', (t) => {
367	  const dir = tempDir(t);
