370	  addResource(df, '乙'); // R0002
371	  createBooking(df, ['R0001', 'R0002'], '2026-10-12T09:00', '2026-10-12T10:00', 'B0001');
372	  const manifest = writeManifest(dir, 'op.json', [
373	    {bookingId: 'B0001', start: '2026-10-12T14:00', end: '2026-10-12T15:00', resourceIds: ['R0001', 'R0002']},
374	  ]);
375	  ok(df, ['reschedule-batch', manifest], '批量改期 O0001');
376	
377	  // 构造阻挡：批外预约占用 R0001 的原时段；R0002 的原时段被有效停用覆盖
378	  createBooking(df, ['R0001'], '2026-10-12T09:30', '2026-10-12T10:30', '批外预约 B0002');
379	  ok(df, ['add-closure', '--resource', 'R0002', '--start', '2026-10-12T08:00', '--end', '2026-10-12T12:00'], '有效停用 C0001');
380	
381	  const bytesBefore = readFileSync(df);
382	  const r = bizFail(df, ['undo-batch-op', 'O0001'], '恢复受阻');
383	  assert.ok(r.stderr.includes('B0001'), '列出失败项');
384	  assert.ok(r.stderr.includes('C0001'), '列出相关停用标识');
385	  assert.ok(r.stderr.includes('2026-10-12T08:00') && r.stderr.includes('2026-10-12T12:00'), '列出相关停用时间');
386	  assert.ok(r.stderr.includes('B0002'), '列出冲突预约');
387	  assert.ok(r.stderr.includes('R0001'), '列出共同资源');
