389	  let store = readStore(df);
390	  assertArrangement(store, 'B0001', '2026-10-12T14:00', '2026-10-12T15:00', ['R0001', 'R0002'], '整笔不变');
391	  assert.equal(store.batchOps[0].status, 'active', '记录状态不变');
392	
393	  // 解除全部阻挡后恢复成功
394	  ok(df, ['cancel-closure', 'C0001'], '解除停用阻挡');
395	  ok(df, ['cancel-booking', 'B0002'], '解除批外预约阻挡');
