1	// shiftbook iCalendar 导入（import-ical）自动化回归测试
2	//
3	// 运行：npm test（等价于 node --test test/，本文件随全部测试一起执行）
4	// 说明：
5	// - 使用 Node.js 24 内置测试运行器（node:test），无外部依赖、不访问网络；
6	// - 全部经命令行入口（node app.ts --data <临时文件>）操作，不读取用户默认数据文件；
7	// - 每个场景使用独立临时数据目录，保存结果由新进程查询或直接读取数据文件断言；
8	// - 任一断言失败即非零退出，输出中标注场景与步骤；结束后自动清理临时文件。
9	
10	import {test} from 'node:test';
11	import assert from 'node:assert/strict';
12	import {spawnSync} from 'node:child_process';
13	import {mkdtempSync, rmSync, writeFileSync, readFileSync, mkdirSync} from 'node:fs';
14	import {tmpdir} from 'node:os';
15	import {join, dirname} from 'node:path';
16	import {fileURLToPath} from 'node:url';
17	
18	const APP = join(dirname(fileURLToPath(import.meta.url)), '..', 'app.ts');
19	const OPEN_ALL: Array<[string, string]> = [['2026-01-01T00:00', '2027-01-01T00:00']];
20	
21	// ---------------------------------------------------------------------------
22	// 基础设施
23	// ---------------------------------------------------------------------------
24	
25	interface CliResult {
26	  status: number;
27	  stdout: string;
28	  stderr: string;
29	}
30	
31	function runCli(dataFile: string, args: string[]): CliResult {
32	  const r = spawnSync(process.execPath, [APP, '--data', dataFile, ...args], {encoding: 'utf8'});
33	  if (r.error) throw r.error;
34	  return {status: r.status ?? -1, stdout: r.stdout ?? '', stderr: r.stderr ?? ''};
35	}
36	
37	function ok(df: string, args: string[], ctx: string): CliResult {
38	  const r = runCli(df, args);
39	  assert.equal(
40	    r.status,
41	    0,
42	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
43	  );
44	  return r;
45	}
46	
47	function bizFail(df: string, args: string[], ctx: string): CliResult {
48	  const r = runCli(df, args);
49	  assert.equal(
50	    r.status,
51	    1,
52	    `[${ctx}] 期望退出 1，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
53	  );
54	  return r;
55	}
56	
57	function usageFail(df: string, args: string[], ctx: string): CliResult {
58	  const r = runCli(df, args);
59	  assert.equal(
60	    r.status,
61	    2,
62	    `[${ctx}] 期望退出 2，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
63	  );
64	  return r;
65	}
66	
67	function tempDir(t: {after: (fn: () => void) => void}): string {
68	  const dir = mkdtempSync(join(tmpdir(), 'shiftbook-ical-test-'));
69	  t.after(() => rmSync(dir, {recursive: true, force: true}));
70	  return dir;
71	}
72	
73	function addResource(df: string, name: string, open: Array<[string, string]> = OPEN_ALL): void {
74	  const args = ['add-resource', '--type', 'venue', '--name', name];
75	  for (const [s, e] of open) args.push('--open', `${s}/${e}`);
76	  ok(df, args, `登记资源 ${name}`);
77	}
78	
79	function writeIcal(dir: string, name: string, content: string): string {
80	  const p = join(dir, name);
81	  writeFileSync(p, content, 'utf8');
82	  return p;
83	}
84	
85	function event(uid: string, start: string, end: string, extra = ''): string {
86	  return `BEGIN:VEVENT\nUID:${uid}\nDTSTART:${start}\nDTEND:${end}\n${extra}END:VEVENT\n`;
87	}
88	
89	function ical(...events: string[]): string {
90	  return `BEGIN:VCALENDAR\nVERSION:2.0\n${events.join('')}END:VCALENDAR\n`;
91	}
92	
93	function readStore(df: string): any {
94	  return JSON.parse(readFileSync(df, 'utf8'));
95	}
96	
97	function importOk(df: string, icalFile: string, resources: string[], ctx: string): CliResult {
98	  const args = ['import-ical', icalFile];
99	  for (const r of resources) args.push('--resource', r);
100	  return ok(df, args, ctx);
101	}
102	
103	function importBizFail(df: string, icalFile: string, resources: string[], ctx: string): CliResult {
104	  const args = ['import-ical', icalFile];
105	  for (const r of resources) args.push('--resource', r);
106	  return bizFail(df, args, ctx);
107	}
108	
109	// ---------------------------------------------------------------------------
110	// 1. 基本导入：两个事件各生成一项普通预约，导入身份与预约原子落盘
111	// ---------------------------------------------------------------------------
112	
113	test('基本导入：新事件生成普通预约并持久关联 UID', (t) => {
114	  const dir = tempDir(t);
115	  const df = join(dir, 'data.json');
116	  addResource(df, '一号会议室');
117	  addResource(df, '投影仪');
118	
119	  const f = writeIcal(dir, 'a.ics', ical(
120	    event('meeting-001@example.com', '20261012T100000', '20261012T110000', 'SUMMARY:周例会\n'),
121	    event('meeting-002@example.com', '20261012T140000', '20261012T153000', 'DESCRIPTION:忽略我\n'),
122	  ));
123	  const r = importOk(df, f, ['R0001', 'R0002'], '首次导入');
124	  assert.match(r.stdout, /新增 2 项，重放 0 项/);
125	  assert.match(r.stdout, /meeting-001@example\.com.*B0001/);
126	  assert.match(r.stdout, /meeting-002@example\.com.*B0002/);
127	  assert.match(r.stdout, /2026-10-12T10:00 → 2026-10-12T11:00/);
128	
129	  const store = readStore(df);
130	  assert.equal(store.bookingSeq, 2);
131	  assert.equal(store.bookings.length, 2);
132	  assert.equal(store.bookings[0].status, 'active');
133	  assert.equal(store.bookings[0].seriesId, undefined, '导入预约不加入系列');
134	  assert.deepEqual(store.bookings[0].resourceIds, ['R0001', 'R0002']);
135	  assert.equal(store.imports.length, 2);
136	  const imp = store.imports.find((x: any) => x.uid === 'meeting-001@example.com');
137	  assert.ok(imp, '导入身份已持久化');
138	  assert.equal(imp.bookingId, 'B0001');
139	  assert.equal(imp.start, '2026-10-12T10:00');
140	  assert.equal(imp.end, '2026-10-12T11:00');
141	  assert.deepEqual(imp.resourceIds, ['R0001', 'R0002']);
142	});
143	
144	// ---------------------------------------------------------------------------
145	// 2. 重放：相同 UID 与相同原请求（资源顺序、折行、转义差异不算变化），
146	//    全为重放不写文件、不推进计数
147	// ---------------------------------------------------------------------------
148	
149	test('重放：资源顺序/折行/转义差异不算变化，全为重放不写文件', (t) => {
150	  const dir = tempDir(t);
151	  const df = join(dir, 'data.json');
152	  addResource(df, '会议室');
153	  addResource(df, '投影仪');
154	
155	  // CRLF + 折行 + 转义 UID（a\,b）+ 小写属性名
156	  const f1 = writeIcal(
157	    dir,
158	    'first.ics',
159	    'BEGIN:VCALENDAR\r\nVERSION:2.0\r\nBEGIN:VEVENT\r\nuid:a\\,b-long-uid-fold\r\n ed@example.com\r\nDtStart:20261012T100000\r\nDTEND:20261012T110000\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n',
160	  );
161	  importOk(df, f1, ['R0001', 'R0002'], '首次导入（CRLF/折行/转义）');
162	  const before = readFileSync(df);
163	
164	  // 同一 UID 的另一种写法：LF、不折行、资源顺序颠倒 —— 仍是重放
165	  const f2 = writeIcal(
166	    dir,
167	    'second.ics',
168	    ical(event('a,b-long-uid-folded@example.com', '20261012T100000', '20261012T110000')),
169	  );
170	  const r = importOk(df, f2, ['R0002', 'R0001'], '重放（LF/不同写法/资源顺序颠倒）');
171	  assert.match(r.stdout, /全部为重放/);
172	  assert.match(r.stdout, /重放，未做改动/);
173	  assert.match(r.stdout, /当前状态: 已预约/);
174	  assert.ok(before.equals(readFileSync(df)), '全为重放时数据文件逐字节不变');
175	  const store = readStore(df);
176	  assert.equal(store.bookingSeq, 1, '计数不推进');
