180	// ---------------------------------------------------------------------------
181	// 3. 重放不复活：原预约被改期或取消后，重放返回当前安排与状态且不改动
182	// ---------------------------------------------------------------------------
183	
184	test('重放：原预约被改期/取消后不复活、不重建，返回当前安排与状态', (t) => {
185	  const dir = tempDir(t);
186	  const df = join(dir, 'data.json');
187	  addResource(df, '会议室');
188	
189	  const f = writeIcal(dir, 'a.ics', ical(event('uid-x', '20261012T100000', '20261012T110000')));
190	  importOk(df, f, ['R0001'], '首次导入');
