    const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
    if (shared.length > 0) internal.push({other: o, shared});
  }
  if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
    failures.push({target: t, gaps, external, internal});
  }
}

